style.css:
/* พื้นหลังภาพนิ่ง */
body {
    background-image: url("https://i.postimg.cc/25PkvsPF/wallpaperbetter.jpg"); /* ใส่ URL ของภาพของคุณ */
    background-size: cover;        /* ให้เต็มหน้าจอ */
    background-repeat: no-repeat;  /* ไม่ซ้ำ */
    background-position: center;   /* จัดตรงกลาง */
}

/* Keyframes กระพริบแดง–ดำสมูธ */
@keyframes redBlackSmooth {
    0%   { color: red; }
    50%  { color: black; }
    100% { color: red; }
}

/* ใช้กับทุกตัวอักษรบนเว็บ Roblox */
body, body * {
    animation: redBlackSmooth 3s infinite ease-in-out; /* ลื่นและสมูธ */
    transition: color 1.5s ease-in-out;               /* เพิ่มความลื่นเวลาเปลี่ยนสี */
}
